        mom = m[-1] - m[0]
        if mom > 10:
            out['A'] = 1.0
        elif mom < -10:
            out['A'] = 0.0
    out['B'] = 0.0
    out['C'] = 0.0
    out['IDX'] = 0.0
    out['A.X'] = 0.0
    out['B.X'] = 0.0
    out['C.X'] = 0.0
    return out
